import math

def is_multiply_prime(a):
    """
    Returns True if the given number is the multiplication of 3 prime numbers,
    and False otherwise. Assumes that a is less than 100.

    :param a: Integer, the number to check.
    :return: Boolean, True if a is the product of three prime numbers, False otherwise.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    def prime_factors(n):
        """Return the prime factors of a number."""
        factors = []
        while n % 2 == 0:
            factors.append(2)
            n //= 2
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            while n % i == 0:
                factors.append(i)
                n //= i
        if n > 2:
            factors.append(n)
        return factors

    factors = prime_factors(a)
    return len(factors) == 3 and all(is_prime(factor) for factor in factors)
