def order_by_points(nums):
    """
    Sorts the given list of integers in ascending order according to the sum of their digits.
    If there are several items with similar sum of their digits, order them based on their index in the original list.

    :param nums: List of integers to be sorted.
    :return: A new list of integers sorted by the sum of their digits, with original indices preserved for ties.
    """
    def digit_sum(n):
        return sum(abs(int(d)) for d in str(n))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))
