from math import comb

def eulerian_num(n, m):
    """
    Returns the Eulerian number a(n, m), which is the number of permutations of the numbers 1 to n
    in which exactly m elements are greater than the previous element.
    """
    if m < 0 or m >= n:
        return 0
    if m == 0:
        return 1
    if m == n - 1:
        return 1
    return sum(comb(n - k - 1, m - k) * eulerian_num(k, m - k) for k in range(1, n - m))
